(()=>{document.querySelectorAll('.status').forEach(e=>e.setAttribute('role','status'));const byId=id=>document.getElementById(id),on=(id,type,fn)=>byId(id)?.addEventListener(type,fn),status=(id,text)=>{const e=byId(id);if(e)e.textContent=text;};on('appearance','change',e=>document.documentElement.style.colorScheme=e.target.value);
on('incognito','change',e=>status('identity',e.target.checked?'Profile shared: randomly generated sample name · incognito':'Profile shared: Austin · sample profile'));
on('create-invite','click',()=>{byId('invite').hidden=false;byId('accept-invite').disabled=false;byId('revoke-invite').disabled=false;status('invite-state','Waiting for someone to connect · simulation');});on('accept-invite','click',()=>{status('invite-state','Connection established in this simulation. This is not identity verification.');byId('accept-invite').disabled=true;byId('revoke-invite').disabled=true;});on('revoke-invite','click',()=>{byId('invite').hidden=true;status('identity','Invitation cancelled in this demo.');});on('address-toggle','click',e=>{const a=byId('address');a.hidden=!a.hidden;e.target.setAttribute('aria-expanded',String(!a.hidden));});on('scan-note','click',()=>status('scan-status','In the native app, this opens the existing camera/QR flow. Camera access is not implemented in this study.'));
const profiles={personal:['Personal',[['Maya','Shall we go on Saturday?'],['Family','Lunch on Sunday?']]],work:['Work',[['Studio','The new sketches are ready.'],['Alex','The review is at two.']]]};document.querySelectorAll('[data-profile]').forEach(button=>button.addEventListener('click',()=>{const [name,chats]=profiles[button.dataset.profile];status('profile-name',name);const area=byId('profile-messages');area.replaceChildren();for(const [person,message]of chats){const row=document.createElement('div');row.className='row';const span=document.createElement('span'),p=document.createElement('p');span.textContent=person;p.className='note';p.textContent=message;span.append(p);row.append(span);area.append(row);}document.querySelectorAll('[data-profile]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));on('show-previews','change',e=>byId('profile-messages').classList.toggle('private',!e.target.checked));on('unlock-profile','click',()=>status('unlock-status','Native authentication would run here. This prototype leaves hidden profiles undisclosed.'));
on('verify-toggle','click',e=>{const panel=byId('verification');panel.hidden=!panel.hidden;e.target.setAttribute('aria-expanded',String(!panel.hidden));});on('verified-demo','click',()=>status('verified-status','Match confirmation simulated. No real connection has been verified.'));
const reply=byId('reply');if(reply){reply.value=sessionStorage.getItem('simplex-v2-maya-draft')||'';byId('send-reply').disabled=!reply.value.trim();}on('reply','input',e=>{sessionStorage.setItem('simplex-v2-maya-draft',e.target.value);byId('send-reply').disabled=!e.target.value.trim();status('reply-status','Draft retained in this browser tab session · not sent.');});on('send-reply','click',()=>{const input=byId('reply');if(!input.value.trim())return;const p=document.createElement('div');p.className='message';const small=document.createElement('small');small.textContent='You · simulated send';p.append(small,document.createTextNode(input.value.trim()));byId('sent-messages').append(p);input.value='';sessionStorage.removeItem('simplex-v2-maya-draft');byId('send-reply').disabled=true;status('reply-status','Send simulated. No message was delivered.');});
let joined=false;function groupRole(){const observer=byId('role')?.value==='observer';status('role-description',observer?'Observer · reads but cannot send':'Member · may send messages');if(byId('group-message')){byId('group-message').disabled=observer||!joined;byId('send-group').disabled=observer||!joined||!byId('group-message').value.trim();}if(joined)status('membership','Joined in demo · '+(observer?'observer':'member'));}on('role','change',groupRole);on('join-group','click',()=>{joined=true;byId('group-pending').hidden=true;byId('group-joined').hidden=false;status('invitation-status','Membership accepted in this simulation; no date agreement is implied.');groupRole();});on('decline-group','click',()=>{status('invitation-status','Invitation declined. You did not join.');byId('join-group').disabled=true;byId('decline-group').disabled=true;});on('group-message','input',groupRole);on('send-group','click',()=>{if(!joined||byId('role').value==='observer'||!byId('group-message').value.trim())return;byId('group-message').value='';status('group-status','Group message send simulated. Nothing delivered.');groupRole();});on('leave-group','click',()=>{joined=false;byId('group-joined').hidden=true;byId('group-pending').hidden=false;status('invitation-status','Left the sample group. No membership remains in this simulation.');groupRole();});groupRole();})();
